def reconcile_physical_stock(apps, schema_editor):
    Product = apps.get_model('inventory', 'Product')
    OrderItem = apps.get_model('orders', 'OrderItem')
    DeliveryItem = apps.get_model('orders', 'DeliveryItem')
    
    for product in Product.objects.all():
        active_items = OrderItem.objects.filter(
            product_id=product.id,
            order__order_status__in=['confirmed', 'completed'],
            order__cancellation_status__in=['na', 'pending']
        )
        
        owed = 0
        for item in active_items:
            # sum delivery items
            delivery_items = DeliveryItem.objects.filter(order_item_id=item.id)
            delivered_qty = sum(di.quantity for di in delivery_items)
            
            base = item.confirmed_quantity if item.confirmed_quantity is not None else item.quantity
            remaining = max(0, base - delivered_qty)
            owed += remaining
            
        new_physical = product.stock_quantity + owed
        if product.physical_stock != new_physical:
            product.physical_stock = new_physical
            product.save(update_fields=['physical_stock'])

